// Third-party notices (Preferences > About > Third-party licenses). The data is
// src/lib/licenses/licenses.json, generated by `pnpm licenses` (scripts/licenses.mjs) and loaded
// as its own lazy chunk: read as text and parsed, so TypeScript never types the large file. It lists
// every platform we ship; the app shows the running platform's ([`forPlatform`]).

import { isMac } from "$lib/platform";

/** The platforms Kinetra ships on. */
export type Platform = "windows" | "macos";

export type LicenseFile = { name: string; text: number };
export type LicenseItem = {
  name: string;
  version: string;
  /** SPDX expression (or the package's own license field). */
  license: string;
  /** The copyright holder, when the license file doesn't name one. */
  copyright?: string;
  /** Repository or homepage. */
  url?: string;
  /** npm package of a font family. */
  package?: string;
  /** License files shipped with the package; `text` indexes `Licenses.texts`. */
  files?: LicenseFile[];
  /** Shipped on these platforms only (a Rust crate with platform-only code); absent = all. */
  platforms?: Platform[];
};
export type LicenseGroup = { id: "npm" | "rust" | "fonts" | "ndi"; label: string; items: LicenseItem[] };
export type Licenses = { schemaVersion: 1; depsHash: string; groups: LicenseGroup[]; texts: string[] };

let loading: Promise<Licenses> | undefined;

/** The running platform. */
export const currentPlatform = (): Platform => (isMac() ? "macos" : "windows");

/** The notices of what ships on `platform`: items for other platforms only are left out. */
export function forPlatform(data: Licenses, platform: Platform): Licenses {
  return {
    ...data,
    groups: data.groups.map((g) => ({
      ...g,
      items: g.items.filter((i) => !i.platforms || i.platforms.includes(platform)),
    })),
  };
}

/** The generated notices for this platform (one dynamic import, cached; retried after a failure). */
export function loadLicenses(): Promise<Licenses> {
  loading ??= import("./licenses.json?raw").then((m) => forPlatform(JSON.parse(m.default) as Licenses, currentPlatform()));
  loading.catch(() => (loading = undefined));
  return loading;
}

/** Groups narrowed to items whose name, package, version or license contains `query` (case-insensitive). */
export function filterLicenses(groups: LicenseGroup[], query: string): LicenseGroup[] {
  const q = query.trim().toLowerCase();
  if (!q) return groups;
  return groups.map((g) => ({
    ...g,
    items: g.items.filter((i) =>
      [i.name, i.package ?? "", i.version, i.license].some((s) => s.toLowerCase().includes(q)),
    ),
  }));
}
